<?php
require __DIR__ . '/app/bootstrap.php'; require __DIR__ . '/app/layout.php';
require_once __DIR__ . '/app/roster.php';
$admin = require_login();
if (($admin['role_slug'] ?? '') !== 'super-admin') { http_response_code(403); exit('Super Admin access required.'); }
$pdo = db(); $error = ''; $notice = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string) ($_POST['action'] ?? ''); $type = (string) ($_POST['type'] ?? ''); $id = (int) ($_POST['id'] ?? 0);
    $existingLeave = $type === 'event' ? roster_leave_load($id) : null;
    try {
        if (!$existingLeave) $pdo->beginTransaction();
        $beforeQuery = $pdo->prepare($type === 'event' ? 'SELECT * FROM calendar_events WHERE id=? FOR UPDATE' : 'SELECT * FROM company_holidays WHERE id=? FOR UPDATE');
        $beforeQuery->execute([$id]);
        $before = $beforeQuery->fetch();
        if (!$before) throw new InvalidArgumentException('That calendar entry no longer exists.');
        if ($action === 'delete' && $type === 'event' && ($leave = roster_leave_load($id))) { $result = roster_leave_delete($id, $admin); if (!$result['ok']) throw new InvalidArgumentException($result['error']); $notice=$result['message'] ?? 'Leave deleted.'; }
        elseif ($action === 'edit' && $type === 'event' && ($leave = roster_leave_load($id))) { $result = roster_leave_save(['staff_id'=>$leave['staff_id'], 'start_date'=>(string)($_POST['event_date']??''), 'end_date'=>(string)($_POST['end_date']??''), 'leave_type'=>$leave['leave_type'], 'notes'=>$leave['notes']], $admin, $id); if (!$result['ok']) throw new InvalidArgumentException($result['error']); $notice='Leave updated.'; }
        elseif ($action === 'delete' && $type === 'event') { $pdo->prepare('DELETE FROM calendar_events WHERE id=?')->execute([$id]); audit_admin_action((int)$admin['id'],'calendar_event_deleted','calendar_event',$id,['before'=>$before]); $notice='Event deleted.'; }
        elseif ($action === 'delete' && $type === 'holiday') { $pdo->prepare('DELETE FROM company_holidays WHERE id=?')->execute([$id]); audit_admin_action((int)$admin['id'],'company_holiday_deleted','company_holiday',$id,['before'=>$before]); $notice='Holiday deleted.'; }
        elseif ($action === 'edit' && $type === 'event') { $title=trim((string)($_POST['title']??''));$date=(string)($_POST['event_date']??'');$end=trim((string)($_POST['end_date']??''));$eventType=(string)($_POST['event_type']??'');if($title===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||($end!==''&&$end<$date)||!in_array($eventType,['team_event','coverage','reminder','other'],true))throw new InvalidArgumentException('Enter valid event details.');$pdo->prepare('UPDATE calendar_events SET title=?,event_date=?,end_date=?,event_type=? WHERE id=?')->execute([$title,$date,$end?:null,$eventType,$id]);audit_admin_action((int)$admin['id'],'calendar_event_updated','calendar_event',$id,['before'=>$before,'after'=>['title'=>$title,'event_date'=>$date,'end_date'=>$end?:null,'event_type'=>$eventType]]);$notice='Event updated.'; }
        elseif ($action === 'edit' && $type === 'holiday') { $label=trim((string)($_POST['label']??''));$date=(string)($_POST['date']??'');$country=(string)($_POST['country_code']??'');if($label===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!in_array($country,['COMPANY','PH','AU','CA'],true))throw new InvalidArgumentException('Enter valid holiday details.');$pdo->prepare('UPDATE company_holidays SET `date`=?,label=?,country_code=?,holiday_type=? WHERE id=?')->execute([$date,$label,$country,$country==='COMPANY'?'company':'public',$id]);audit_admin_action((int)$admin['id'],'company_holiday_updated','company_holiday',$id,['before'=>$before,'after'=>['date'=>$date,'label'=>$label,'country_code'=>$country]]);$notice='Holiday updated.'; }
        if ($pdo->inTransaction()) $pdo->commit();
    } catch (Throwable $exception) { if ($pdo->inTransaction()) $pdo->rollBack(); $error=$exception instanceof InvalidArgumentException?$exception->getMessage():'Calendar change could not be saved.'; }
}
$eventVisibility = app_schema_has('calendar_events', 'deleted_at', $pdo) ? ' WHERE deleted_at IS NULL' : '';
$events=$pdo->query('SELECT * FROM calendar_events' . $eventVisibility . ' ORDER BY event_date DESC, id DESC')->fetchAll();$holidays=$pdo->query('SELECT * FROM company_holidays ORDER BY `date` DESC, id DESC')->fetchAll();
page_start('Calendar administration',$admin); ?><?php if($error):?><p class="auth-error"><?=e($error)?></p><?php endif;?><?php if($notice):?><p class="action-notice"><?=e($notice)?></p><?php endif;?><section><h2>Events</h2><?php foreach($events as $event):?><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="type" value="event"><input type="hidden" name="id" value="<?=$event['id']?>"><label>Title<input name="title" value="<?=e($event['title'])?>" required<?php if($event['event_type']==='leave'):?> readonly aria-describedby="leave-title-help-<?= (int)$event['id'] ?>"<?php endif;?>><?php if($event['event_type']==='leave'):?><small id="leave-title-help-<?= (int)$event['id'] ?>" class="field-help">Leave titles are generated from the staff member and leave type.</small><?php endif;?></label><label>Type<select name="event_type"><?php foreach(($event['event_type']==='leave' ? ['leave'=>'Staff leave'] : ['team_event'=>'Team event','coverage'=>'Coverage','reminder'=>'Reminder','other'=>'Other']) as $key=>$label):?><option value="<?=$key?>" <?=$event['event_type']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Start<input type="date" name="event_date" value="<?=e($event['event_date'])?>" required></label><label>End<input type="date" name="end_date" value="<?=e($event['end_date']??'')?>"></label><button class="button">Save</button><button class="button button-danger" name="action" value="delete" formnovalidate data-confirm="Delete this event?">Delete</button></form><?php endforeach;?><?php if(!$events):?><p class="muted">No events.</p><?php endif;?></section><section><h2>Holidays</h2><?php foreach($holidays as $holiday):?><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="holiday"><input type="hidden" name="id" value="<?=$holiday['id']?>"><label>Label<input name="label" value="<?=e($holiday['label'])?>" required></label><label>Country<select name="country_code"><?php foreach(['COMPANY'=>'Company','PH'=>'Philippines','AU'=>'Australia','CA'=>'Canada'] as $key=>$label):?><option value="<?=$key?>" <?=$holiday['country_code']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Date<input type="date" name="date" value="<?=e($holiday['date'])?>" required></label><button class="button" name="action" value="edit">Save</button><button class="button button-danger" name="action" value="delete" formnovalidate data-confirm="Delete this holiday?">Delete</button></form><?php endforeach;?><?php if(!$holidays):?><p class="muted">No holidays.</p><?php endif;?></section><script>document.querySelectorAll('[data-confirm]').forEach(function(button){button.addEventListener('click',function(event){if(!window.confirm(button.dataset.confirm))event.preventDefault();});});</script><?php page_end();
